from pwn import *
import time

binary = '/home/ctfplayer/ctf_files/share/share/chal/unsafe-linking'

def try_menu_inputs():
    p = process(binary)
    menu = p.recvuntil(b'> ', timeout=3).decode()
    print('Initial menu:\n', menu)

    # Try each menu item and log output
    for choice in [b'1', b'2', b'3', b'4']:
        p.sendline(choice)
        out = ''
        if choice == b'1':  # Create a note
            try:
                out = p.recvuntil(b'> ', timeout=2).decode()
            except Exception:
                out = p.recv(timeout=1).decode(errors='ignore')
        elif choice == b'2':  # Delete a note
            try:
                out = p.recvuntil(b'> ', timeout=2).decode()
            except Exception:
                out = p.recv(timeout=1).decode(errors='ignore')
        elif choice == b'3':  # Read a note
            try:
                out = p.recvuntil(b'> ', timeout=2).decode()
            except Exception:
                out = p.recv(timeout=1).decode(errors='ignore')
        elif choice == b'4':  # Exit
            try:
                out = p.recvall(timeout=2).decode(errors='ignore')
            except Exception:
                out = ''
        print(f'\n--- Output for menu item {choice.decode()} ---\n{out}')
        if choice == b'4':
            break

if __name__ == '__main__':
    try_menu_inputs()

